query:
mutation IssueCreate($input: IssueCreateInput!) {
  issueCreate(input: $input) {
    success
    issue {
      id identifier title description updatedAt priority estimate
      state { id name type }
      team { id key }
      assignee { id }
      cycle { id }
      project { id }
      parent { id identifier }
      labels { nodes { id } }
    }
  }
}
